public class Main {
    static int score(int x) {
        return switch (x) {
            case 1 -> 10;
            case 2 -> {
                int y = x * 5;
                yield y + 1;
            }
            default -> 0;
        };
    }
    public static void main(String[] args) {
        System.out.print(score(1) + ":" + score(2) + ":" + score(3));
    }
}

